```javascript
/**
 * Bubble Sort (ascending) with input validation.
 *
 * Bubble Sort idea:
 * Repeatedly pass through the array, swapping adjacent out-of-order elements.
 * After each full pass, the largest remaining element "bubbles" to the end.
 *
 * Time complexity:
 * - Worst / Average: O(n^2)
 * - Best (already sorted with early-exit): O(n)
 * Space complexity: O(1) extra space (in-place, aside from optional copy).
 */

const MAX_LEN = 100;
const MIN_VAL = -10000;
const MAX_VAL = 10000;

/**
 * Validates that the input is an array of integers with allowed length and range.
 * Throws a TypeError/RangeError for invalid inputs.
 * @param {any} arr
 */
function validateIntArray(arr) {
  if (!Array.isArray(arr)) {
    throw new TypeError("Input must be an array.");
  }
  if (arr.length > MAX_LEN) {
    throw new RangeError(`Array length must be <= ${MAX_LEN}.`);
  }

  for (let i = 0; i < arr.length; i++) {
    const v = arr[i];
    if (!Number.isInteger(v)) {
      throw new TypeError(`Element at index ${i} must be an integer.`);
    }
    if (v < MIN_VAL || v > MAX_VAL) {
      throw new RangeError(
        `Element at index ${i} must be between ${MIN_VAL} and ${MAX_VAL}.`
      );
    }
  }
}

/**
 * Sorts an array of integers in ascending order using Bubble Sort.
 * By default, returns a new sorted array (does not mutate input).
 *
 * @param {number[]} arr - Array of integers to sort.
 * @param {object} [options]
 * @param {boolean} [options.inPlace=false] - If true, sorts the original array.
 * @returns {number[]} The sorted array.
 */
function bubbleSort(arr, { inPlace = false } = {}) {
  validateIntArray(arr);

  // Choose whether to mutate the input or work on a copy.
  const a = inPlace ? arr : arr.slice();
  const n = a.length;

  // Outer loop: after each pass, the last element of the unsorted portion is correct.
  for (let i = 0; i < n - 1; i++) {
    let swapped = false;

    // Inner loop: compare adjacent pairs within the remaining unsorted range.
    for (let j = 0; j < n - 1 - i; j++) {
      if (a[j] > a[j + 1]) {
        // Swap adjacent elements
        const tmp = a[j];
        a[j] = a[j + 1];
        a[j + 1] = tmp;
        swapped = true;
      }
    }

    // Early exit: if no swaps occurred, the array is already sorted.
    if (!swapped) break;
  }

  return a;
}

/* Example usage with error handling */
try {
  const input = [5, -2, 9, 1, 5, 6];
  const sorted = bubbleSort(input); // non-mutating by default
  console.log("Original:", input);
  console.log("Sorted:", sorted);
} catch (err) {
  // Proper error handling: surface a meaningful message
  console.error(`${err.name}: ${err.message}`);
}
